"use strict";(function(){"use strict";if(globalThis.cssosAbVariant)return;const cache=new Map;async function fetchVariant(experimentId){try{const res=await fetch("/api/ab/assignment/"+encodeURIComponent(experimentId),{credentials:"include",headers:{Accept:"application/json"}});if(!res.ok)return null;const j=await res.json().catch(()=>null);return!j||j.ok!==!0?null:String(j.variant||"")||null}catch{return null}}async function cssosAbVariant(experimentId,callback){const id=String(experimentId||"").trim();if(!id)return null;cache.has(id)||cache.set(id,fetchVariant(id));const variant=await cache.get(id);if(variant&&typeof callback=="function")try{callback(variant)}catch(err){console.warn("[ab] callback failed:",err)}return variant}function cssosAbConvert(experimentId,payload){const id=String(experimentId||"").trim();if(id)try{fetch("/api/ab/event",{method:"POST",credentials:"include",headers:{"Content-Type":"application/json"},body:JSON.stringify({experiment_id:id,event_kind:"conversion",payload:payload&&typeof payload=="object"?payload:{}}),keepalive:!0}).catch(()=>{})}catch{}}globalThis.cssosAbVariant=cssosAbVariant,globalThis.cssosAbConvert=cssosAbConvert})();
